def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    urgent_opp = 0
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
            if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 3:
                urgent_opp += 1

    if not alive:
        return float(min(budget, 18.0))

    high_supply = supply >= 22
    low_supply = supply <= 17
    very_risky = hp <= 3 or no_water >= 1

    top_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    target = 0.0

    if very_risky:
        if top_prev > 0:
            target = top_prev + 3.0
        else:
            target = DAILY_SALARY * 0.95
    elif low_supply:
        if top_prev >= 110:
            target = max(78.0, top_prev + 2.0)
        elif top_prev > 0:
            target = max(62.0, top_prev + 2.0)
        else:
            target = 66.0
    elif high_supply:
        if hp >= 7 and no_water == 0:
            target = 22.0
        else:
            target = 38.0
    else:
        if top_prev >= 120:
            target = 36.0 if hp >= 6 and no_water == 0 else 82.0
        elif avg_prev >= 90:
            target = 52.0
        else:
            target = 58.0

    if urgent_opp >= 2 and not very_risky:
        target -= 6.0
    if day >= 8 and hp >= 6 and no_water == 0 and not low_supply:
        target -= 6.0
    if hp <= 2:
        target = max(target, top_prev + 5.0 if top_prev > 0 else 90.0)
    if no_water >= 2:
        target = max(target, top_prev + 8.0 if top_prev > 0 else 110.0)

    target = max(0.0, target)
    return float(min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 140
    WATER_REQ = 8
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.3)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if my_status['hp'] <= 2 or my_status['no_water_days'] >= 1:
        if yesterday_bids:
            max_prev = max(yesterday_bids)
            target = max(DAILY_SALARY * 0.85, max_prev + 2)
        else:
            target = DAILY_SALARY * 0.85
        return min(my_status['budget'], target)

    if yesterday_bids:
        max_prev = max(yesterday_bids)
        target = max(DAILY_SALARY * 0.5, max_prev + 1)
        target = min(target, DAILY_SALARY * 0.9)
    else:
        target = DAILY_SALARY * 0.5
    return min(my_status['budget'], target)
